if(PHP_SAPI!=='cli')exit(1);require_once __DIR__.'/../koneksi.php';require_once __DIR__.'/http_form_scope.php';spp_test_assert_database_target($koneksi);require_once __DIR__.'/../includes/legacy_operational_bank.php';require_once __DIR__.'/../includes/reports.php';require_once __DIR__.'/legacy_finance_support.php';unit_set_context($koneksi,1);$fixture=json_decode(file_get_contents(dirname(getenv('SPP_TEST_ISOLATED_INSTANCE')).'/operational-fixture.json'),true);$cashier=(int)lf_one($koneksi,"SELECT id FROM admin WHERE role='kasir' AND unit_id=1 AND is_active=1 LIMIT 1")['id'];$_SESSION=['admin_id'=>$cashier,'admin_role'=>'kasir','active_unit_id'=>1];$owner=lf_one($koneksi,"SELECT * FROM legacy_op_owners WHERE batch_id=? AND source_identity='GK01'",[$fixture['job']]);$key=bin2hex(random_bytes(32));$input=['direction'=>'in','amount'=>'100','date'=>date('Y-m-d H:i:s'),'note'=>'Owned operator-filter and replay fixture'];$before=lf_one($koneksi,'SELECT balance FROM legacy_op_accounts WHERE owner_id=?',[$owner['id']]);lop_bank_new($koneksi,$cashier,1,(int)$owner['id'],$input,$key);lop_bank_new($koneksi,$cashier,1,(int)$owner['id'],$input,$key);lft_assert(lf_cents(lf_one($koneksi,'SELECT balance FROM legacy_op_accounts WHERE owner_id=?',[$owner['id']])['balance'])===lf_cents($before['balance'])+10000,'Bank retry duplicated');lft_reject(fn()=>lop_bank_new($koneksi,$cashier,1,(int)$owner['id'],array_replace($input,['amount'=>'101']),$key),'Changed request reused key');$f=report_filters($koneksi,['operator'=>(string)$cashier,'tanggal_awal'=>date('Y-m-d'),'tanggal_akhir'=>date('Y-m-d')]);$rows=report_savings_transactions($koneksi,date('Y-m-d').' 00:00:00',date('Y-m-d',strtotime('+1 day')).' 00:00:00',$f);$newJournalId=(int)lf_one($koneksi,'SELECT entity_id FROM legacy_op_audit WHERE request_key=?',[$key])['entity_id'];$own=array_filter($rows,fn($r)=>(int)$r['id']===-(1000000000+$newJournalId)&&$r['NO_INDUK']==='rekening:'.$owner['id']&&($r['legacy_origin']??'')==='new');lft_ass